-- P.U.M.A. (Piattaforma Unificata Monitoraggio Addestramenti): schema del modulo.
-- Solo CREATE IF NOT EXISTS / INSERT OR IGNORE: non tocca i dati esistenti.

CREATE TABLE IF NOT EXISTS puma_attivita(id INTEGER PRIMARY KEY, titolo TEXT NOT NULL, tipo TEXT, descrizione TEXT, data_inizio TEXT, data_fine TEXT, stato TEXT NOT NULL DEFAULT 'attiva', comando_id INTEGER NOT NULL, direzione_id INTEGER, is_blindato INTEGER NOT NULL DEFAULT 0, is_condiviso_nazionale INTEGER NOT NULL DEFAULT 0, creato_da TEXT, creato_il TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS puma_addestramenti(id INTEGER PRIMARY KEY, attivita_id INTEGER REFERENCES puma_attivita(id), data TEXT NOT NULL, ora TEXT, luogo TEXT, tema TEXT NOT NULL, istruttore TEXT, partecipanti TEXT, stato TEXT NOT NULL DEFAULT 'programmato', comando_id INTEGER NOT NULL, direzione_id INTEGER, is_blindato INTEGER NOT NULL DEFAULT 0, is_condiviso_nazionale INTEGER NOT NULL DEFAULT 0, creato_da TEXT, creato_il TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS puma_documenti(id INTEGER PRIMARY KEY, categoria TEXT NOT NULL, titolo TEXT NOT NULL, settore TEXT, filename TEXT NOT NULL, comando_id INTEGER NOT NULL, direzione_id INTEGER, is_blindato INTEGER NOT NULL DEFAULT 0, is_condiviso_nazionale INTEGER NOT NULL DEFAULT 0, creato_da TEXT, creato_il TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS puma_settori(codice TEXT PRIMARY KEY, nome TEXT NOT NULL);
INSERT OR IGNORE INTO puma_settori VALUES('SAF','SAF – Speleo Alpino Fluviale'),('TPSS','TPSS – Topografia Applicata al Soccorso');
CREATE TABLE IF NOT EXISTS puma_livelli(id INTEGER PRIMARY KEY, settore TEXT NOT NULL, nome TEXT NOT NULL, mesi_validita INTEGER NOT NULL DEFAULT 12, UNIQUE(settore,nome));
INSERT OR IGNORE INTO puma_livelli(settore,nome) VALUES('SAF','SAF Basico'),('SAF','SAF Avanzato'),('TPSS','Retraining TPSS');
CREATE TABLE IF NOT EXISTS puma_manovre(id INTEGER PRIMARY KEY, livello_id INTEGER NOT NULL REFERENCES puma_livelli(id), nome TEXT NOT NULL, ordine INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS puma_config(comando_id INTEGER NOT NULL, chiave TEXT NOT NULL, valore TEXT, PRIMARY KEY(comando_id,chiave));
CREATE TABLE IF NOT EXISTS puma_destinatari(comando_id INTEGER NOT NULL, ruolo TEXT NOT NULL, email TEXT NOT NULL, PRIMARY KEY(comando_id,ruolo,email));
CREATE TABLE IF NOT EXISTS puma_eventi(id INTEGER PRIMARY KEY, data TEXT NOT NULL, tipologia TEXT NOT NULL, livello_id INTEGER, team TEXT NOT NULL, titolo TEXT, lat REAL, lon REAL, rv_lat REAL, rv_lon REAL, rv_descr TEXT, stato TEXT NOT NULL DEFAULT 'programmato', meteo TEXT, rischio TEXT, piano_inviato TEXT, responsabile TEXT, comando_id INTEGER NOT NULL, direzione_id INTEGER, is_blindato INTEGER NOT NULL DEFAULT 0, is_condiviso_nazionale INTEGER NOT NULL DEFAULT 0, creato_il TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(data,tipologia,team,comando_id));
CREATE TABLE IF NOT EXISTS puma_checkin(evento_id INTEGER NOT NULL REFERENCES puma_eventi(id), username TEXT NOT NULL, nome TEXT, comando_origine INTEGER, ora TEXT, convalidato INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(evento_id,username));
CREATE TABLE IF NOT EXISTS puma_individuali(id INTEGER PRIMARY KEY, username TEXT NOT NULL, tipologia TEXT NOT NULL, livello_id INTEGER, inizio TEXT NOT NULL, fine TEXT NOT NULL, manovre TEXT, comando_id INTEGER NOT NULL, direzione_id INTEGER, is_blindato INTEGER NOT NULL DEFAULT 0, is_condiviso_nazionale INTEGER NOT NULL DEFAULT 0, creato_il TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS puma_interventi(id INTEGER PRIMARY KEY, username TEXT NOT NULL, macro TEXT NOT NULL, data TEXT NOT NULL, descrizione TEXT, comando_id INTEGER NOT NULL, direzione_id INTEGER, is_blindato INTEGER NOT NULL DEFAULT 0, is_condiviso_nazionale INTEGER NOT NULL DEFAULT 0, creato_il TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS puma_alert_inviati(username TEXT, livello_id INTEGER, scadenza TEXT, PRIMARY KEY(username,livello_id,scadenza));
-- Sotto-settori P.U.M.A. = settori del portale (abilitazioni dal pannello Utenti)
INSERT OR IGNORE INTO settori(codice,nome,descrizione) VALUES('saf','SAF','P.U.M.A. - Speleo Alpino Fluviale'),('tpss','TPSS','P.U.M.A. - Topografia Applicata al Soccorso');
